-- 004 — Guia de Supervisão de Loja (Grupo Milla) carregado na área Supervisão Comercial:
-- papel, pilares, rotina na loja, programação mensal por semana, roteiro de conversa com o gerente
-- e os checklists estruturados de Visita à Loja e Visita à Concorrência (blocos, pesos e ações sugeridas).
-- Checklists com "estrutura" passam a ter cabeçalho, observação por item, índice ponderado,
-- classificação e plano de ação sugerido gerado no salvamento.

ALTER TABLE checklist_modelos ADD COLUMN IF NOT EXISTS estrutura JSONB;
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS cabecalho JSONB;
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS indice_ponderado INT;
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS classificacao TEXT;

UPDATE areas
   SET papel = $t$Primeira liderança comercial: responsável pelos gerentes das lojas, ligada aos pilares de resultado e pessoas. Não é cobrador — é quem desenvolve, padroniza e acelera a execução, da abertura ao fechamento da loja.$t$,
       tag = 'Condução da loja no dia a dia: rotina, visitas, checklists e concorrência',
