-- O checklist simples de loja dá lugar ao checklist completo do guia (aplicações antigas continuam consultáveis).
UPDATE checklist_modelos SET ativo = FALSE WHERE area_id = 'comercial' AND nome = 'Checklist de Loja (execução)';

